    trapExamples: [{ question: "パンや（朝9時〜夕がた6時）は、夜7時に あいて いますか。", wrongAnswer: "あいて いる", trapExplanation: "夕がた6時に しまる ことを 見ずに、朝から あいて いる ことだけ 見て しまった。", correctAnswer: "あいて いない", correctExplanation: "夕がた6時に しまる。夜7時は それより あとなので、もう しまって いる。" }],
